/bin/zsh -c "python3 -B -c 'import json,pathlib,hashlib,itertools
h=lambda b:hashlib.sha256(b.encode()).hexdigest()
pl=json.loads(pathlib.Path(\"source/plan.json\").read_text())
pr=json.loads(pathlib.Path(\"provenance.json\").read_text())
for p in pl[\"propositions\"]:
 t=pathlib.Path(\"source/props\")/p[\"id\"]/\"statement.md\"
 target=pr[\"approvals\"][p[\"id\"]][\"contract_hash\"]
 variants={\"statement\":p[\"statement\"],\"statement newline\":p[\"statement\"]+\"\\n\",\"body\":t.read_text().split(\"\\n\\n\",1)[1],\"body stripped\":t.read_text().split(\"\\n\\n\",1)[1].strip()}
 matches=[k for k,v in variants.items() if h(v)==target]
 for n in range(1,len(p)+1):
  for keys in itertools.combinations(p.keys(),n):
   d={k:p[k] for k in keys}
   for sort in [True,False]:
    for ascii in [True,False]:
     for sep in [None,(\",\",\":\")]:
      v=json.dumps(d,sort_keys=sort,ensure_ascii=ascii,separators=sep)
      if h(v)==target:matches.append(str((keys,sort,ascii,sep)))
 print(p[\"id\"],matches)
acc=json.loads(pathlib.Path(\"source/numerics/accepted.json\").read_text())
target=json.loads(pathlib.Path(\"manuscript/build-inputs.json\").read_text())[\"accepted_snapshot\"]
for sort in [True,False]:
 for ascii in [True,False]:
  for sep in [None,(\",\",\":\")]:
   for indent in [None,2]:
    for end in [\"\",\"\\n\"]:
     if h(json.dumps(acc,sort_keys=sort,ensure_ascii=ascii,separators=sep,indent=indent)+end)==target:print(\"accepted hash normalization\",sort,ascii,sep,indent,repr(end))
'"

